SELECT * FROM (select rownum rn, tb.* from (
select test_no , (SELECT t.member_id FROM test_bank t JOIN member m ON(t.member_id = m.member_id) WHERE authority = (SELECT sub_cd_nm FROM sub_cd WHERE sub_cd = 'A102')) as member_id , subject_no , FIND_CODENAME(subject_no) as subject_no_nm , test_type , FIND_CODENAME(test_type) as test_type_nm , test_detail , test_img , test_commentary , commentary_img , test_score , test_correct from test_bank
order by test_no DESC
) tb) WHERE rn BETWEEN #{startNo} AND #{endNo}
